//! `cargo xtask seeds` — one package-selection declaration, every generated artifact.
//!
//! `distro/seeds/selection.toml` is the only hand-written package list in the repository. The seed
//! files, the two mkosi package drop-ins and every metapackage `control.in` are rendered from it,
//! so a package can be added, removed or explained in exactly one place. `--check` (and
//! `check-packaging`, which calls the same function) fails when a generated file has drifted, which
//! is what stops the old failure mode: a name added to the image list and forgotten in the
//! metapackage, or a seed nothing consumes.
//!
//! `seeds closure` is deliberately separate from generation: generation is pure and always works,
//! resolution needs an archive index and frequently does not. The report says which of the three
//! states it is in rather than presenting a partial answer as a closure.

use anyhow::{Context, Result, bail};
use serde::Deserialize;
use std::fmt::Write as _;
use std::{
    collections::{BTreeMap, BTreeSet},
    path::Path,
    process::Command as Process,
};

/// Every generated file starts with this line. A file without it was written by hand.
const BANNER: &str =
    "# GENERATED by `cargo xtask seeds` from distro/seeds/selection.toml — do not edit.";

pub const DECLARATION: &str = "distro/seeds/selection.toml";

// ---------------------------------------------------------------------------------------------
// The declaration
// ---------------------------------------------------------------------------------------------

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Selection {
    pub version: u32,
    #[serde(default)]
    pub policy: Policy,
    #[serde(default, rename = "layer")]
    pub layers: Vec<Layer>,
    #[serde(default, rename = "metapackage")]
    pub metapackages: Vec<Metapackage>,
}

#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Policy {
    #[serde(default)]
    pub conflicts: Vec<String>,
    #[serde(default)]
    pub recommends: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Layer {
    pub id: String,
    pub title: String,
    pub kind: LayerKind,
    #[serde(default)]
    pub variant_group: String,
    #[serde(default)]
    pub default: bool,
    pub image: bool,
    pub stage: Stage,
    #[serde(default, rename = "package")]
    pub packages: Vec<Package>,
}

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum LayerKind {
    Required,
    Optional,
    Variant,
}

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum Stage {
    /// `10-packages-base.conf` — what must exist before anything else is resolved.
    Base,
    /// `50-seeds.conf` — everything else.
    Seeds,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Package {
    pub name: String,
    pub reason: String,
    #[serde(default)]
    pub role: Option<String>,
    #[serde(default)]
    pub kind: PackageKind,
    #[serde(default)]
    pub arch: Option<String>,
    /// Flatpak entries only: the remote the ref is installed from.
    #[serde(default)]
    pub remote: Option<String>,
    /// Rendered as `Recommends:` rather than `Depends:` on the metapackages: the package is part
    /// of the selection, but a set without it must still install. Only for a package that is
    /// not yet buildable (`reason` says why); not a way to make a dependency optional for good.
    #[serde(default)]
    pub recommends: bool,
}

#[derive(Clone, Copy, Debug, Default, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum PackageKind {
    #[default]
    Deb,
    /// A Flatpak ref. Recorded and reported, never written into an apt package list (ADR-0011).
    Flatpak,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Metapackage {
    pub package: String,
    pub directory: String,
    pub architecture: String,
    #[serde(default)]
    pub layers: Vec<String>,
    #[serde(default)]
    pub extra_depends: Vec<String>,
    #[serde(default)]
    pub recommends: Vec<String>,
    #[serde(default)]
    pub conflicts: Vec<String>,
    #[serde(default)]
    pub policy_conflicts: bool,
    pub description: String,
    pub description_body: String,
}

impl Selection {
    pub fn read(root: &Path) -> Result<Self> {
        let path = root.join(DECLARATION);
        let text = std::fs::read_to_string(&path)
            .with_context(|| format!("reading {}", path.display()))?;
        let selection: Self =
            toml::from_str(&text).with_context(|| format!("parsing {}", path.display()))?;
        let problems = selection.problems();
        if !problems.is_empty() {
            for problem in &problems {
                eprintln!("seeds: {problem}");
            }
            bail!("{} problem(s) in {DECLARATION}", problems.len());
        }
        Ok(selection)
    }

    fn layer(&self, id: &str) -> Option<&Layer> {
        self.layers.iter().find(|layer| layer.id == id)
    }

    /// The layers a machine actually gets: every non-variant layer, plus the default member of
    /// each variant group. Two members of one group are never selected together, which is why a
    /// package may appear in both of them without being a duplicate.
    fn selected(&self) -> Vec<&Layer> {
        let mut selected: Vec<&Layer> = Vec::new();
        let mut groups: BTreeSet<&str> = BTreeSet::new();
        for layer in &self.layers {
            if layer.kind == LayerKind::Variant {
                if layer.default && groups.insert(layer.variant_group.as_str()) {
                    selected.push(layer);
                }
            } else {
                selected.push(layer);
            }
        }
        selected
    }

    /// Everything wrong with the declaration itself, before anything is rendered from it.
    fn problems(&self) -> Vec<String> {
        let mut problems = Vec::new();
        if self.version != 1 {
            problems.push(format!(
                "version {} is not 1; this generator only understands version 1",
                self.version
            ));
        }
        let banned: BTreeSet<&str> = self.policy.conflicts.iter().map(String::as_str).collect();
        let mut seen_layers: BTreeSet<&str> = BTreeSet::new();
        let mut where_declared: BTreeMap<&str, Vec<&Layer>> = BTreeMap::new();
        for layer in &self.layers {
            if !seen_layers.insert(layer.id.as_str()) {
                problems.push(format!("layer {} is declared twice", layer.id));
            }
            if (layer.kind == LayerKind::Variant) == layer.variant_group.is_empty() {
                problems.push(format!(
                    "layer {}: variant_group and kind = \"variant\" go together or not at all",
                    layer.id
                ));
            }
            for package in &layer.packages {
                if package.reason.trim().is_empty() {
                    problems.push(format!(
                        "{}: {} has no reason; a name nobody can explain is a name nobody can remove",
                        layer.id, package.name
                    ));
                }
                if package.kind == PackageKind::Flatpak && package.remote.is_none() {
                    problems.push(format!(
                        "{}: flatpak ref {} names no remote, so nothing can install it",
                        layer.id, package.name
                    ));
                }
                if banned.contains(package.name.as_str()) {
                    problems.push(format!(
                        "{}: {} is in [policy].conflicts and must never be selected",
                        layer.id, package.name
                    ));
                }
                where_declared
                    .entry(package.name.as_str())
                    .or_default()
                    .push(layer);
            }
        }
        problems.extend(duplicate_package_problems(&where_declared));
        problems.extend(self.variant_group_problems());
        problems.extend(duplicate_provider_problems(&self.selected()));
        for meta in &self.metapackages {
            for id in &meta.layers {
                if self.layer(id).is_none() {
                    problems.push(format!(
                        "metapackage {} names layer {id}, which is not declared",
                        meta.package
                    ));
                }
            }
        }
        problems
    }

    fn variant_group_problems(&self) -> Vec<String> {
        let mut defaults: BTreeMap<&str, usize> = BTreeMap::new();
        for layer in &self.layers {
            if layer.kind == LayerKind::Variant {
                let count = defaults.entry(layer.variant_group.as_str()).or_default();
                if layer.default {
                    *count += 1;
                }
            }
        }
        defaults
            .into_iter()
            .filter(|&(_, count)| count != 1)
            .map(|(group, count)| {
                format!("variant group {group} has {count} default layers; exactly one is selected")
            })
            .collect()
    }
}

/// A package declared in two layers that can be installed together. Members of one variant group
/// are mutually exclusive, so the same name in both of them is the intended way to say "either
/// flavour needs this".
fn duplicate_package_problems(where_declared: &BTreeMap<&str, Vec<&Layer>>) -> Vec<String> {
    let mut problems = Vec::new();
    for (name, layers) in where_declared {
        for (index, left) in layers.iter().enumerate() {
            for right in &layers[index + 1..] {
                let exclusive = left.kind == LayerKind::Variant
                    && right.kind == LayerKind::Variant
                    && left.variant_group == right.variant_group;
                if !exclusive {
                    problems.push(format!(
                        "{name} is declared in both {} and {}; a package belongs to one layer",
                        left.id, right.id
                    ));
                }
            }
        }
    }
    problems
}

/// Two selected packages claiming the same exclusive role — the failure that produces two
/// terminals, two input methods or two portal backends fighting over one protocol.
fn duplicate_provider_problems(selected: &[&Layer]) -> Vec<String> {
    let mut claims: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
    for layer in selected {
        for package in &layer.packages {
            if let Some(role) = package.role.as_deref() {
                claims.entry(role).or_default().push(&package.name);
            }
        }
    }
    claims
        .into_iter()
        .filter(|(_, packages)| packages.len() > 1)
        .map(|(role, packages)| {
            format!(
                "role {role} is claimed by {}; a provider role is exclusive",
                packages.join(", ")
            )
        })
        .collect()
}

// ---------------------------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------------------------

/// Every file this command owns, as `(repository-relative path, content)`.
pub fn artifacts(selection: &Selection) -> Vec<(String, String)> {
    let mut artifacts = Vec::new();
    for layer in &selection.layers {
        artifacts.push((
            format!("distro/seeds/{}.seed", layer.id),
            render_seed(layer),
        ));
    }
    artifacts.push((
        "distro/seeds/flatpak-refs.list".to_owned(),
        render_flatpak_refs(selection),
    ));
    artifacts.push((
        "distro/image/mkosi.conf.d/10-packages-base.conf".to_owned(),
        render_packages_conf(selection, Stage::Base),
    ));
    artifacts.push((
        "distro/image/mkosi.conf.d/50-seeds.conf".to_owned(),
        render_packages_conf(selection, Stage::Seeds),
    ));
    for meta in &selection.metapackages {
        artifacts.push((
            format!("distro/metapackages/{}/control.in", meta.directory),
            render_control(selection, meta),
        ));
    }
    artifacts
}

fn render_seed(layer: &Layer) -> String {
    let mut out = format!("{BANNER}\n# {} — {}\n", layer.id, layer.title);
    for package in &layer.packages {
        match package.kind {
            PackageKind::Deb => {
                let _ = writeln!(out, "{}", package.name);
            }
            PackageKind::Flatpak => {
                let _ = writeln!(out, "# flatpak: {}", package.name);
            }
        }
    }
    out
}

/// The Flatpak refs the image cannot install itself. apt never sees these (ADR-0011), so without
/// a list of their own the browser would be declared and installed by nothing — the gap X1 found.
/// First boot (`distro/image/mkosi.postinst`, D3) and the provisioner consume this file:
/// `<remote> <ref>` per line, comments and blanks ignored.
fn render_flatpak_refs(selection: &Selection) -> String {
    let mut out =
        format!("{BANNER}\n# <remote> <ref> — installed after first boot, never by apt.\n");
    for layer in &selection.layers {
        for package in &layer.packages {
            if package.kind == PackageKind::Flatpak {
                let _ = writeln!(
                    out,
                    "{} {}",
                    package.remote.as_deref().unwrap_or("flathub"),
                    package.name
                );
            }
        }
    }
    out
}

fn render_packages_conf(selection: &Selection, stage: Stage) -> String {
    let mut out = format!("{BANNER}\n[Content]\nPackages=\n");
    for layer in &selection.layers {
        if !layer.image || layer.stage != stage {
            continue;
        }
        for package in &layer.packages {
            if package.kind == PackageKind::Deb {
                let _ = writeln!(out, "        {}", package.name);
            }
        }
    }
    out
}

/// One metapackage's `control.in`. `${misc:Depends}` is appended to every `Depends:` because every
/// metapackage needs it and forgetting it is a lintian error nobody sees until packaging time.
fn render_control(selection: &Selection, meta: &Metapackage) -> String {
    let mut depends: Vec<String> = Vec::new();
    let mut recommends: Vec<String> = Vec::new();
    for id in &meta.layers {
        if let Some(layer) = selection.layer(id) {
            for package in &layer.packages {
                if package.kind != PackageKind::Deb {
                    continue;
                }
                if package.recommends {
                    recommends.push(package.name.clone());
                } else {
                    depends.push(package.name.clone());
                }
            }
        }
    }
    depends.extend(meta.extra_depends.iter().cloned());
    depends.push("${misc:Depends}".to_owned());
    recommends.extend(meta.recommends.iter().cloned());

    let mut conflicts = meta.conflicts.clone();
    if meta.policy_conflicts {
        conflicts.extend(selection.policy.conflicts.iter().cloned());
    }

    let mut out = format!(
        "{BANNER}\nPackage: {}\nArchitecture: {}\n{}",
        meta.package,
        meta.architecture,
        fold("Depends", &depends)
    );
    if !recommends.is_empty() {
        out.push_str(&fold("Recommends", &recommends));
    }
    if !conflicts.is_empty() {
        out.push_str(&fold("Conflicts", &conflicts));
    }
    let _ = writeln!(out, "Description: {}", meta.description);
    for line in meta.description_body.trim().lines() {
        let _ = writeln!(out, " {}", line.trim());
    }
    out
}

/// A Debian field folded at roughly 90 columns, continuation lines indented by one space.
fn fold(field: &str, values: &[String]) -> String {
    let mut out = format!("{field}:");
    let mut column = out.len();
    for (index, value) in values.iter().enumerate() {
        let last = index + 1 == values.len();
        let piece = if last {
            value.clone()
        } else {
            format!("{value},")
        };
        if column + piece.len() + 1 > 90 {
            out.push_str("\n ");
            column = 1;
        } else {
            out.push(' ');
            column += 1;
        }
        column += piece.len();
        out.push_str(&piece);
    }
    out.push('\n');
    out
}

// ---------------------------------------------------------------------------------------------
// Generate / check
// ---------------------------------------------------------------------------------------------

/// Seed files on disk that the declaration no longer produces — a renamed or deleted layer's
/// leftovers, which would otherwise keep being read by everything that globs `*.seed`.
fn stale_seeds(root: &Path, generated: &BTreeSet<String>) -> Result<Vec<String>> {
    let dir = root.join("distro/seeds");
    let mut stale = Vec::new();
    if !dir.is_dir() {
        return Ok(stale);
    }
    for entry in std::fs::read_dir(&dir).context("reading distro/seeds")? {
        let path = entry?.path();
        if path.extension().and_then(|e| e.to_str()) != Some("seed") {
            continue;
        }
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_default();
        let relative = format!("distro/seeds/{name}");
        if !generated.contains(&relative) {
            stale.push(relative);
        }
    }
    Ok(stale)
}

pub fn generate(root: &Path) -> Result<()> {
    let selection = Selection::read(root)?;
    let artifacts = artifacts(&selection);
    let generated: BTreeSet<String> = artifacts.iter().map(|(path, _)| path.clone()).collect();
    for (path, content) in &artifacts {
        let full = root.join(path);
        if let Some(parent) = full.parent() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("creating {}", parent.display()))?;
        }
        std::fs::write(&full, content).with_context(|| format!("writing {}", full.display()))?;
    }
    for path in stale_seeds(root, &generated)? {
        std::fs::remove_file(root.join(&path)).with_context(|| format!("removing stale {path}"))?;
        println!("seeds: removed stale {path}");
    }
    println!(
        "seeds: {} layer(s), {} metapackage(s), {} generated file(s) from {DECLARATION}",
        selection.layers.len(),
        selection.metapackages.len(),
        artifacts.len()
    );
    Ok(())
}

/// Where a generated file and the declaration disagree. `check-packaging` reports these too, so a
/// hand-edited seed or control file fails the ordinary gate rather than surviving to image build.
pub fn drift(root: &Path) -> Result<Vec<String>> {
    let selection = Selection::read(root)?;
    let artifacts = artifacts(&selection);
    let generated: BTreeSet<String> = artifacts.iter().map(|(path, _)| path.clone()).collect();
    let mut problems = Vec::new();
    for (path, content) in &artifacts {
        match std::fs::read_to_string(root.join(path)) {
            Ok(on_disk) if &on_disk == content => {}
            Ok(_) => problems.push(format!(
                "{path} differs from {DECLARATION}; run `cargo xtask seeds`"
            )),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                problems.push(format!("{path} is missing; run `cargo xtask seeds`"));
            }
            Err(error) => return Err(error).with_context(|| format!("reading {path}")),
        }
    }
    for path in stale_seeds(root, &generated)? {
        problems.push(format!(
            "{path} is not produced by {DECLARATION}; run `cargo xtask seeds` to remove it"
        ));
    }
    Ok(problems)
}

pub fn check(root: &Path) -> Result<()> {
    let problems = drift(root)?;
    if !problems.is_empty() {
        for problem in &problems {
            eprintln!("seeds: {problem}");
        }
        bail!("{} generated file(s) have drifted", problems.len());
    }
    println!("seeds: every generated file matches {DECLARATION}");
    Ok(())
}

// ---------------------------------------------------------------------------------------------
// Closure
// ---------------------------------------------------------------------------------------------

/// What the archive indexes on this machine can honestly say about the selection.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Resolution {
    /// Indexes for the declared codename answered.
    Resolved,
    /// Indexes answered, but for a different release than the one declared.
    ForeignRelease,
    /// No usable archive index at all. Not "nothing missing" — nothing was asked.
    Unavailable,
}

impl Resolution {
    fn as_str(self) -> &'static str {
        match self {
            Self::Resolved => "resolved",
            Self::ForeignRelease => "foreign-release",
            Self::Unavailable => "unavailable",
        }
    }
}

/// What `distro/base.toml` says about the archive: the codename the closure is expected to resolve
/// against, and the snapshot pin. Read as flat keys rather than through a model of that whole file,
/// because it is D3's and D4's file as much as ours and three keys are all this needs.
fn base_facts(root: &Path) -> Result<(String, String, String)> {
    let path = root.join("distro/base.toml");
    let text =
        std::fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
    let value = |key: &str| -> Option<String> {
        text.lines().find_map(|line| {
            let (name, rest) = line.split_once('=')?;
            (name.trim() == key).then(|| {
                rest.split('#')
                    .next()
                    .unwrap_or_default()
                    .trim()
                    .trim_matches('"')
                    .to_owned()
            })
        })
    };
    let Some(codename) = value("codename") else {
        bail!("distro/base.toml declares no [base] codename");
    };
    Ok((
        codename,
        value("snapshot_url").unwrap_or_default(),
        value("snapshot_serial").unwrap_or_default(),
    ))
}

/// The package sources apt would actually answer from, and the codenames they carry.
fn apt_sources() -> (Vec<String>, BTreeSet<String>) {
    let Ok(output) = Process::new("apt-cache").arg("policy").output() else {
        return (Vec::new(), BTreeSet::new());
    };
    if !output.status.success() {
        return (Vec::new(), BTreeSet::new());
    }
    let text = String::from_utf8_lossy(&output.stdout);
    let mut sources = Vec::new();
    let mut codenames = BTreeSet::new();
    for line in text.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix("release ") {
            for field in rest.split(',') {
                if let Some(codename) = field.trim().strip_prefix("n=") {
                    codenames.insert(codename.to_owned());
                }
            }
        } else if trimmed.starts_with(|c: char| c.is_ascii_digit())
            && let Some((_, source)) = trimmed.split_once(' ')
        {
            sources.push(source.to_owned());
        }
    }
    (sources, codenames)
}

/// Ask apt what a set of packages would drag in. `--simulate` needs no privileges and writes
/// nothing; `Inst <name>` lines are what it would install.
fn simulate(direct: &[String], recommends: bool) -> Option<BTreeSet<String>> {
    let mut command = Process::new("apt-get");
    command.args(["--simulate", "--quiet"]);
    if !recommends {
        command.arg("--no-install-recommends");
    }
    command.arg("install");
    command.args(direct);
    let output = command.output().ok()?;
    if !output.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&output.stdout);
    Some(
        text.lines()
            .filter_map(|line| line.strip_prefix("Inst "))
            .filter_map(|rest| rest.split_whitespace().next())
            .map(ToOwned::to_owned)
            .collect(),
    )
}

/// `Installed-Size` (kibibytes) summed over whatever apt knows about.
fn installed_size_bytes(packages: &BTreeSet<String>) -> u64 {
    if packages.is_empty() {
        return 0;
    }
    let Ok(output) = Process::new("apt-cache")
        .arg("show")
        .args(packages.iter())
        .output()
    else {
        return 0;
    };
    String::from_utf8_lossy(&output.stdout)
        .lines()
        .filter_map(|line| line.strip_prefix("Installed-Size:"))
        .filter_map(|value| value.trim().parse::<u64>().ok())
        .sum::<u64>()
        * 1024
}

/// UTC, ISO-8601, from the epoch — the provenance stamp D2 reads. No date crate for one timestamp.
fn iso8601(unix: i64) -> String {
    let days = unix.div_euclid(86_400);
    let seconds = unix.rem_euclid(86_400);
    // Howard Hinnant's civil_from_days.
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if month <= 2 { year + 1 } else { year };
    format!(
        "{year:04}-{month:02}-{day:02}T{:02}:{:02}:{:02}Z",
        seconds / 3600,
        (seconds % 3600) / 60,
        seconds % 60
    )
}

fn now_unix() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |d| d.as_secs() as i64)
}

/// Which of the three honest states this machine is in, and why in one sentence.
fn resolution_state(
    declared: &str,
    sources: &[String],
    codenames: &BTreeSet<String>,
) -> (Resolution, String) {
    if codenames.iter().any(|name| name == declared) {
        return (
            Resolution::Resolved,
            format!("apt has indexes for the declared release {declared}"),
        );
    }
    if codenames.is_empty() {
        return (
            Resolution::Unavailable,
            format!(
                "no archive index for any release is present ({}); direct packages and providers \
                 are still valid, an empty `missing` list means nothing was asked",
                if sources.is_empty() {
                    "apt-cache policy answered nothing".to_owned()
                } else {
                    sources.join(", ")
                }
            ),
        );
    }
    (
        Resolution::ForeignRelease,
        format!(
            "apt answered from {} rather than the declared {declared}; sizes and closure are \
             indicative only",
            codenames.iter().cloned().collect::<Vec<_>>().join(", ")
        ),
    )
}

/// Tiers: a name this repository builds (the workspace packages, the metapackages, the pinned
/// forks) is `native` and can never be in an Ubuntu index; everything else is `inherited` and
/// must be. Tags every direct entry and returns `(inherited, native)` names, so only the inherited
/// ones are asked of apt and one native name does not turn the simulation into "nothing resolves".
fn tag_tiers(root: &Path, direct: &mut [serde_json::Value]) -> Result<(Vec<String>, Vec<String>)> {
    let control_text =
        std::fs::read_to_string(root.join("debian/control")).context("reading debian/control")?;
    let native_set =
        crate::built_package_names(root, &crate::parse_control_packages(&control_text))?;
    let (mut inherited, mut native) = (Vec::new(), Vec::new());
    for entry in direct.iter_mut() {
        let name = entry["name"].as_str().unwrap_or_default().to_owned();
        let is_native = native_set.contains(&name);
        entry["tier"] = if is_native { "native" } else { "inherited" }.into();
        if is_native {
            &mut native
        } else {
            &mut inherited
        }
        .push(name);
    }
    Ok((inherited, native))
}

pub fn closure(root: &Path, out: Option<&Path>) -> Result<()> {
    let selection = Selection::read(root)?;
    let (declared, snapshot_url, snapshot_serial) = base_facts(root)?;
    let (sources, codenames) = apt_sources();
    let (resolution, note) = resolution_state(&declared, &sources, &codenames);

    let mut direct = Vec::new();
    let mut flatpak = Vec::new();
    let mut roles = serde_json::Map::new();
    for layer in selection.selected() {
        if !layer.image {
            continue;
        }
        for package in &layer.packages {
            if let Some(role) = package.role.as_deref() {
                roles.insert(role.to_owned(), package.name.clone().into());
            }
            let entry = serde_json::json!({
                "name": package.name,
                "layer": layer.id,
                "reason": package.reason,
                "role": package.role,
                "arch": package.arch.clone().unwrap_or_else(|| "any".to_owned()),
            });
            if package.kind == PackageKind::Flatpak {
                flatpak.push(entry);
            } else {
                direct.push(entry);
            }
        }
    }
    let (names, native) = tag_tiers(root, &mut direct)?;

    let resolved = resolution != Resolution::Unavailable;
    let with = resolved.then(|| simulate(&names, true)).flatten();
    let without = resolved.then(|| simulate(&names, false)).flatten();
    let transitive: Vec<String> = with.clone().unwrap_or_default().into_iter().collect();
    let would_drop: Vec<String> = match (&with, &without) {
        (Some(with), Some(without)) => with.difference(without).cloned().collect(),
        _ => Vec::new(),
    };
    let missing: Vec<String> = if resolved {
        names
            .iter()
            .filter(|name| !known_to_apt(name))
            .cloned()
            .collect()
    } else {
        Vec::new()
    };
    let size = with.as_ref().map_or(0, installed_size_bytes);

    let report = serde_json::json!({
        "version": 1,
        "observed_at": iso8601(now_unix()),
        "observed_at_unix": now_unix(),
        "profile": "image layers + the default variant of each group",
        "resolution": resolution.as_str(),
        "resolution_note": note,
        "resolved_against": {
            "declared": {"codename": declared},
            "observed": {"codenames": codenames, "sources": sources},
            "snapshot_url": snapshot_url,
            "snapshot_serial": snapshot_serial,
        },
        "policy": {"recommends": selection.policy.recommends, "conflicts": selection.policy.conflicts},
        "direct": direct,
        "transitive": transitive,
        "installed_size_bytes": size,
        "recommends": {
            "count": would_drop.len(),
            "no_recommends_experiment": {
                "would_drop": would_drop,
                "assessment": if resolved {
                    "packages only a Recommends pulls in; removing them is a policy decision, not a generation detail"
                } else {
                    "not measured: no archive index answered"
                },
            },
        },
        "missing": missing,
        "native": native,
        "roles": roles,
        "flatpak": flatpak,
    });
    let text = serde_json::to_string_pretty(&report)? + "\n";
    match out {
        Some(path) => {
            std::fs::write(path, &text).with_context(|| format!("writing {}", path.display()))?;
            println!(
                "seeds closure: {} ({} inherited + {} native direct package(s), {} missing) -> {}",
                resolution.as_str(),
                names.len(),
                native.len(),
                missing.len(),
                path.display()
            );
        }
        None => print!("{text}"),
    }
    Ok(())
}

/// Whether apt has any candidate for a name at all.
fn known_to_apt(name: &str) -> bool {
    Process::new("apt-cache")
        .args(["policy", name])
        .output()
        .is_ok_and(|output| {
            String::from_utf8_lossy(&output.stdout).contains(&format!("{name}:"))
                && !String::from_utf8_lossy(&output.stdout).contains("Candidate: (none)")
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    const DECLARATION_FIXTURE: &str = r#"
version = 1
[policy]
conflicts = ["snapd"]
recommends = "on"

[[layer]]
id = "session"
title = "the session"
kind = "required"
image = true
stage = "seeds"
[[layer.package]]
name = "legeos-comp"
reason = "the compositor"
role = "compositor"
[[layer.package]]
name = "org.mozilla.firefox"
kind = "flatpak"
remote = "flathub"
reason = "the browser, sandboxed"
role = "browser"

[[layer]]
id = "bootstrap"
title = "the base"
kind = "required"
image = true
stage = "base"
[[layer.package]]
name = "systemd"
reason = "init"

[[metapackage]]
package = "legeos-session-full"
directory = "legeos-session-meta"
architecture = "all"
layers = ["session"]
conflicts = ["apport"]
policy_conflicts = true
description = "LegeOS session only"
description_body = "The session and its daemons."
"#;

    fn fixture() -> Selection {
        toml::from_str(DECLARATION_FIXTURE).expect("the fixture parses")
    }

    #[test]
    fn generated_conf_equals_declaration() {
        let selection = fixture();
        assert!(
            selection.problems().is_empty(),
            "{:?}",
            selection.problems()
        );
        let artifacts = artifacts(&selection);
        let by_path: BTreeMap<&str, &str> = artifacts
            .iter()
            .map(|(path, content)| (path.as_str(), content.as_str()))
            .collect();

        // The two stages are disjoint, every generated file is banner-first, and a Flatpak ref
        // never reaches an apt package list.
        let base = by_path["distro/image/mkosi.conf.d/10-packages-base.conf"];
        let seeds = by_path["distro/image/mkosi.conf.d/50-seeds.conf"];
        assert!(base.starts_with(BANNER) && seeds.starts_with(BANNER));
        assert!(base.contains("        systemd\n") && !base.contains("legeos-comp"));
        assert!(seeds.contains("        legeos-comp\n") && !seeds.contains("systemd"));
        assert!(!seeds.contains("firefox"), "{seeds}");
        assert_eq!(
            by_path["distro/seeds/session.seed"],
            format!(
                "{BANNER}\n# session — the session\nlegeos-comp\n# flatpak: org.mozilla.firefox\n"
            )
        );
    }

    #[test]
    fn metapackage_render_round_trip() {
        let selection = fixture();
        let control = render_control(&selection, &selection.metapackages[0]);
        let field = |name: &str| -> Vec<String> {
            let mut values = Vec::new();
            let mut inside = false;
            for line in control.lines() {
                match line.split_once(':') {
                    Some((key, rest)) if !key.starts_with(' ') => {
                        inside = key == name;
                        if inside {
                            values.push(rest.to_owned());
                        }
                    }
                    _ if inside && line.starts_with(' ') => values.push(line.to_owned()),
                    _ => inside = false,
                }
            }
            values
                .join(" ")
                .split(',')
                .map(|value| value.trim().to_owned())
                .filter(|value| !value.is_empty())
                .collect()
        };
        assert_eq!(field("Depends"), ["legeos-comp", "${misc:Depends}"]);
        // The declaration's own conflicts and the policy's, in that order, and nothing invented.
        assert_eq!(field("Conflicts"), ["apport", "snapd"]);
        assert!(control.contains("Package: legeos-session-full\n"));
        assert!(control.contains("Description: LegeOS session only\n"));
        assert!(control.contains("\n The session and its daemons.\n"));
        // A Flatpak ref is not a Debian dependency.
        assert!(!control.contains("firefox"));
    }

    #[test]
    fn duplicate_provider_detected() {
        let mut selection = fixture();
        selection.layers[0].packages.push(Package {
            name: "cosmic-term".to_owned(),
            reason: "a second terminal".to_owned(),
            role: Some("terminal".to_owned()),
            kind: PackageKind::Deb,
            arch: None,
            remote: None,
            recommends: false,
        });
        selection.layers[1].packages.push(Package {
            name: "kitty".to_owned(),
            reason: "the terminal".to_owned(),
            role: Some("terminal".to_owned()),
            kind: PackageKind::Deb,
            arch: None,
            remote: None,
            recommends: false,
        });
        let problems = selection.problems();
        assert_eq!(problems.len(), 1, "{problems:?}");
        assert!(problems[0].contains("role terminal"), "{problems:?}");
        assert!(problems[0].contains("cosmic-term"), "{problems:?}");
        assert!(problems[0].contains("kitty"), "{problems:?}");
    }
}
